{
  "headings": [
    {
      "sourceParts": [
        {
          "sourceAlias": "L0358:S0",
          "verbatimText": "4. Other cases decided by the Ministry ofInformation and Communications."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0359:S0",
          "verbatimText": "Article 16. Responsibility ofpublication importers to appraise contents ofimported publications"
        }
      ],
      "semanticFunction": "REGION_STRUCTURE"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0360:S0",
          "verbatimText": "1 . Within 30 days after being granted a publication import business license, the publication"
        },
        {
          "sourceAlias": "L0361:S0",
          "verbatimText": "importer shall issue an internal regulation on content appraisal ofimported publications, send"
        },
        {
          "sourceAlias": "L0362:S0",
          "verbatimText": "such regulation to the Ministry ofInformation and Communications and comply with such"
        },
        {
          "sourceAlias": "L0363:S0",
          "verbatimText": "regulation throughout its operation."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0364:S0",
          "verbatimText": "2. Before distributing imported publications, the head ofthe publication importer shall appraise"
        },
        {
          "sourceAlias": "L0365:S0",
          "verbatimText": "their contents as follows:"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0366:S0",
          "verbatimText": "a/ To establish an appraisal board comprising a leader ofthe publication importer as its"
        },
        {
          "sourceAlias": "L0367:S0",
          "verbatimText": "chairperson, experts in the fields related to the contents ofto-be-appraised publications as its"
        },
        {
          "sourceAlias": "L0368:S0",
          "verbatimText": "members and a staffmember in charge ofpublication content appraisal as its secretary. The"
        },
        {
          "sourceAlias": "L0369:S0",
          "verbatimText": "invitation ofexperts to join the appraisal board shall be decided by the head ofthe publication"
        },
        {
          "sourceAlias": "L0370:S0",
          "verbatimText": "importer;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0371:S0",
          "verbatimText": "b/ The appraisal shall be conducted for each imported publication. Appraisal results shall be"
        },
        {
          "sourceAlias": "L0372:S0",
          "verbatimText": "recorded in minutes to be reported to the Ministry ofInformation and Communications once"
        },
        {
          "sourceAlias": "L0373:S0",
          "verbatimText": "every 3 months;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0374:S0",
          "verbatimText": "c/ In the course ofappraisal, ifdetecting that the contents ofan imported publication violate"
        },
        {
          "sourceAlias": "L0375:S0",
          "verbatimText": "Clause 1, Article 10 ofthe Publication Law, the publication importer may not distribute the"
        },
        {
          "sourceAlias": "L0376:S0",
          "verbatimText": "publication and shall promptly report such to the Ministry ofInformation and Communications."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0377:S0",
          "verbatimText": "3. When receiving the Ministry ofInformation and Communications’ requests for content"
        },
        {
          "sourceAlias": "L0378:S0",
          "verbatimText": "appraisal ofimported publications, heads ofpublication importers shall organize the appraisal"
        },
        {
          "sourceAlias": "L0379:S0",
          "verbatimText": "and report appraisal results in writing."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0380:S0",
          "verbatimText": "Imported publications may be distributed only after obtaining written approval ofthe Ministry of"
        },
        {
          "sourceAlias": "L0381:S0",
          "verbatimText": "Information and Communications."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0382:S0",
          "verbatimText": "Chapter IV"
        }
      ],
      "semanticFunction": "REGION_STRUCTURE"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0383:S0",
          "verbatimText": "PUBLISHING AND DISTRIBUTION OF E-PUBLICATIONS"
        }
      ],
      "semanticFunction": "REGION_STRUCTURE"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0384:S0",
          "verbatimText": "Article 17. Conditions for publishing and distribution ofe-publications"
        }
      ],
      "semanticFunction": "REGION_STRUCTURE"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0385:S0",
          "verbatimText": "1 . The conditions on equipment and technologies for publishing and distribution ofe-"
        },
        {
          "sourceAlias": "L0386:S0",
          "verbatimText": "publications are prescribed at Point a, Clause 1, and Point b, Clause 2, Article 45 ofthe"
        },
        {
          "sourceAlias": "L0387:S0",
          "verbatimText": "Publication Law, specifically as follows:"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0388:S0",
          "verbatimText": "a/ Having a server located in Vietnam, computers and other equipment serving the publishing"
        },
        {
          "sourceAlias": "L0389:S0",
          "verbatimText": "and distribution ofe-publications on the internet;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0390:S0",
          "verbatimText": "b/ Having equipment and software serving the design, layout, and recording ofdata on electronic"
        },
        {
          "sourceAlias": "L0391:S0",
          "verbatimText": "devices;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0392:S0",
          "verbatimText": "c/ Having equipment for transmitting digitalized e-publications after they are edited, formatted"
        },
        {
          "sourceAlias": "L0393:S0",
          "verbatimText": "and stored on electronic devices;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0394:S0",
          "verbatimText": "d/ Having a lawfully registered internet connection line for publishing and distribution ofe-"
        },
        {
          "sourceAlias": "L0395:S0",
          "verbatimText": "publications on the internet;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0396:S0",
          "verbatimText": "dd/ Having technical solutions to control the publishing and distribution ofe-publications,"
        },
        {
          "sourceAlias": "L0397:S0",
          "verbatimText": "including distribution, removal or restoration of e-publications for distribution;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0398:S0",
          "verbatimText": "e/ Having technical equipment and solutions to make statistics ofand manage the number ofe-"
        },
        {
          "sourceAlias": "L0399:S0",
          "verbatimText": "publications already published and distributed;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0400:S0",
          "verbatimText": "g/ Having an storage system meeting technical requirements to store e-publications already"
        },
        {
          "sourceAlias": "L0401:S0",
          "verbatimText": "published and distributed; stored e-publications must ensure the requirements on accuracy,"
        },
        {
          "sourceAlias": "L0402:S0",
          "verbatimText": "integrity, information safety and accessibility as soon as they are created;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0403:S0",
          "verbatimText": "h/ Having a lawful digital certificate in accordance with the law on e-transactions and complying"
        },
        {
          "sourceAlias": "L0404:S0",
          "verbatimText": "with standards and technical regulations on e-publications."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0405:S0",
          "verbatimText": "2. Criteria for technical personnel who operate and manage the process ofpublishing and"
        },
        {
          "sourceAlias": "L0406:S0",
          "verbatimText": "distributing e-publications are prescribed at Point a, Clause 1 and Point a, Clause 2, Article 45 of"
        },
        {
          "sourceAlias": "L0407:S0",
          "verbatimText": "the Publication Law, specifically as follows:"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0408:S0",
          "verbatimText": "a/ Being trained in information technology and having worked in the information technology"
        },
        {
          "sourceAlias": "L0409:S0",
          "verbatimText": "sector for at least 1 year; possessing good political and ethical qualities;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0410:S0",
          "verbatimText": "b/ Being qualified for operating and managing the technical equipment and solutions prescribed"
        },
        {
          "sourceAlias": "L0411:S0",
          "verbatimText": "in Clauses 1 and 3 ofthis Article to serve the publishing and distribution ofe-publications."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0412:S0",
          "verbatimText": "3. The technical measures prescribed at Point b, Clause 1, and Point b, Clause 2, Article 45 ofthe"
        },
        {
          "sourceAlias": "L0413:S0",
          "verbatimText": "Publication Law are specified as follows:"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0414:S0",
          "verbatimText": "a/ Having technical equipment and solutions to prevent and control computer viruses;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0415:S0",
          "verbatimText": "b/ Having technical equipment and solutions to prevent unauthorized access via the internet;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0416:S0",
          "verbatimText": "c/ Having a professional process for responding to information safety and security incidents;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0417:S0",
          "verbatimText": "d/ Having a professional process for identifying interferences that change the contents ofe-"
        },
        {
          "sourceAlias": "L0418:S0",
          "verbatimText": "publications;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0419:S0",
          "verbatimText": "dd/ Having technical solutions as prescribed by the Minister ofInformation and Communications"
        },
        {
          "sourceAlias": "L0420:S0",
          "verbatimText": "to control the digital copyright ofcontent providers and content distribution channels."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0421:S0",
          "verbatimText": "4. The Vietnam’s domain name prescribed at Point c, Clause 1, and Point c, Clause 2, Article 45"
        },
        {
          "sourceAlias": "L0422:S0",
          "verbatimText": "ofthe Publication Law must be a “vn” domain name."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0423:S0",
          "verbatimText": "5. The Minister ofInformation and Communications shall specify appropriate conditions for"
        },
        {
          "sourceAlias": "L0424:S0",
          "verbatimText": "publishing and distribution ofe-publications prescribed in this Article in each period of"
        },
        {
          "sourceAlias": "L0425:S0",
          "verbatimText": "technology development."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0426:S0",
          "verbatimText": "Article 18. Appraisal of e-publication publishing or distribution schemes and registration ofthe"
        },
        {
          "sourceAlias": "L0427:S0",
          "verbatimText": "publishing and distribution ofe-publications"
        }
      ],
      "semanticFunction": "REGION_STRUCTURE"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0428:S0",
          "verbatimText": "1 . The appraisal ofe-publication publishing or distribution schemes is as follows:"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0429:S0",
          "verbatimText": "a/ Publishing houses shall send e-publication publishing schemes and organizations and"
        },
        {
          "sourceAlias": "L0430:S0",
          "verbatimText": "individuals shall send e-publication distribution schemes to the Ministry ofInformation and"
        },
        {
          "sourceAlias": "L0431:S0",
          "verbatimText": "Communications;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0432:S0",
          "verbatimText": "b/ E-publication publishing or distribution schemes must explicitly express the satisfaction ofthe"
        },
        {
          "sourceAlias": "L0433:S0",
          "verbatimText": "conditions prescribed in Article 17 ofthis Decree;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0434:S0",
          "verbatimText": "c/ Within 15 days after receiving a scheme, the Ministry ofInformation and Communications"
        },
        {
          "sourceAlias": "L0435:S0",
          "verbatimText": "shall consider and give its written appraisal opinions."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0436:S0",
          "verbatimText": "2. The registration ofthe publishing and distribution ofe-publications prescribed at Point d,"
        },
        {
          "sourceAlias": "L0437:S0",
          "verbatimText": "Clause 1, and Point d, Clause 2, Article 45 ofthe Publication Law is as follows:"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0438:S0",
          "verbatimText": "a/ Within 60 days after receiving the written approval ofthe Ministry ofInformation and"
        },
        {
          "sourceAlias": "L0439:S0",
          "verbatimText": "Communications, the publishing house or organization or individual shall implement its/his/her"
        },
        {
          "sourceAlias": "L0440:S0",
          "verbatimText": "scheme according to the appraisal opinions ofthe Ministry ofInformation and Communications"
        },
        {
          "sourceAlias": "L0441:S0",
          "verbatimText": "and send a dossier ofregistration for e-publication publishing or distribution to the Ministry of"
        },
        {
          "sourceAlias": "L0442:S0",
          "verbatimText": "Information and Communications. A dossier comprises a written registration for e-publication"
        },
        {
          "sourceAlias": "L0443:S0",
          "verbatimText": "publishing or distribution and a copy ofthe Ministry ofInformation and Communications’"
        },
        {
          "sourceAlias": "L0444:S0",
          "verbatimText": "written approval ofthe scheme;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0445:S0",
          "verbatimText": "b/ Within 20 days after receiving a dossier ofregistration for e-publication publishing or"
        },
        {
          "sourceAlias": "L0446:S0",
          "verbatimText": "distribution, the Ministry ofInformation and Communications shall examine the implementation"
        },
        {
          "sourceAlias": "L0447:S0",
          "verbatimText": "ofthe scheme and grant a written registration ofe-publication publishing or distribution; in case"
        },
        {
          "sourceAlias": "L0448:S0",
          "verbatimText": "ofrefusal to grant the written registration, it shall issue a written reply clearly stating the reason;"
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0449:S0",
          "verbatimText": "c/ Publishing houses may publish e-publications and organizations and individuals may"
        },
        {
          "sourceAlias": "L0450:S0",
          "verbatimText": "distribute e-publications only after obtaining the Ministry ofInformation and Communications’"
        },
        {
          "sourceAlias": "L0451:S0",
          "verbatimText": "registration certification."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0452:S0",
          "verbatimText": "3. The Minister ofInformation and Communications shall provide forms ofthe e-publication"
        },
        {
          "sourceAlias": "L0453:S0",
          "verbatimText": "publishing and distribution scheme, written registration application and registration certification"
        },
        {
          "sourceAlias": "L0454:S0",
          "verbatimText": "prescribed in Clauses 1 and 2 ofthis Article."
        }
      ],
      "semanticFunction": "BODY_INFORMATION"
    },
    {
      "sourceParts": [
        {
          "sourceAlias": "L0455:S0",
          "verbatimText": "Article 19. Classification ofe-publications and requirements on the contents and technical"
        },
        {
          "sourceAlias": "L0456:S0",
          "verbatimText": "conditions ofe-publications"
        }
      ],
      "semanticFunction": "REGION_STRUCTURE"
    },
    {
